import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"wiki 视觉再升级方案（待执行）","description":"","frontmatter":{},"headers":[],"relativePath":"DESIGN-UPGRADE-PLAN.md","filePath":"DESIGN-UPGRADE-PLAN.md","lastUpdated":null}'),o={name:"DESIGN-UPGRADE-PLAN.md"};function t(h,a,n,s,d,u){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="wiki-视觉再升级方案-待执行" tabindex="-1">wiki 视觉再升级方案（待执行） <a class="header-anchor" href="#wiki-视觉再升级方案-待执行" aria-label="Permalink to &quot;wiki 视觉再升级方案（待执行）&quot;">​</a></h1><blockquote><p>状态：已确认方案，暂缓执行。目标 —— 脱离 VitePress 默认模板观感，做出克制、有母题、细节一致的高级审美（参照 Stripe / Linear / Vercel 文档站）。 原则：减法 + 一个贯穿母题 + 细节的极致一致，绝不堆装饰（emoji 已是反面教训）。</p></blockquote><h2 id="现状判断" tabindex="-1">现状判断 <a class="header-anchor" href="#现状判断" aria-label="Permalink to &quot;现状判断&quot;">​</a></h2><p>现在不难看，但一眼能认出是 VitePress——默认三栏布局、默认 hero（放大 logo + 一团光晕）、默认六宫格 feature 卡。模板痕迹集中在这些默认件上。</p><h2 id="统领性母题-航线" tabindex="-1">统领性母题：航线 <a class="header-anchor" href="#统领性母题-航线" aria-label="Permalink to &quot;统领性母题：航线&quot;">​</a></h2><p>呼应品牌纸飞机与「自由港」之名。用一条极细的曲线航迹作为视觉线索，出现在 hero 背景、章节之间的分隔，克制到几乎无意识。这是让全站「像一个作品」而非「一套模板」的关键，也是唯一允许张扬的地方。</p><h2 id="高杠杆改动-效果最明显" tabindex="-1">高杠杆改动（效果最明显） <a class="header-anchor" href="#高杠杆改动-效果最明显" aria-label="Permalink to &quot;高杠杆改动（效果最明显）&quot;">​</a></h2><h3 id="_1-hero-重做" tabindex="-1">1. Hero 重做 <a class="header-anchor" href="#_1-hero-重做" aria-label="Permalink to &quot;1. Hero 重做&quot;">​</a></h3><p>放弃默认「放大 logo」，改成有构图的画面：</p><ul><li>左侧标题用更讲究的字号 / 字重 / 字距层次</li><li>右侧不是孤零零的图标，而是「航线母题 + 品牌图」组成的安静构图</li><li>第一印象决定「这站有没有设计」</li></ul><h3 id="_2-教程截图统一呈现-杠杆最大-手册主体" tabindex="-1">2. 教程截图统一呈现（杠杆最大，手册主体） <a class="header-anchor" href="#_2-教程截图统一呈现-杠杆最大-手册主体" aria-label="Permalink to &quot;2. 教程截图统一呈现（杠杆最大，手册主体）&quot;">​</a></h3><p>现在截图是裸图直接贴。改成：</p><ul><li>桌面截图套一层极简窗口边框（三个圆点 + 圆角标题栏）</li><li>手机截图统一圆角 + 柔和投影 + 居中限宽</li><li>全站几十张图立刻像「一套」，专业感飙升</li><li>实现：自定义 markdown 容器或图片包裹组件（纯 CSS）</li></ul><h3 id="_3-底色分层-字体" tabindex="-1">3. 底色分层 + 字体 <a class="header-anchor" href="#_3-底色分层-字体" aria-label="Permalink to &quot;3. 底色分层 + 字体&quot;">​</a></h3><ul><li>默认「性冷淡纯白」换成 Cloud Dancer 暖白的微妙分层（hero / 内容 / 卡片三层）</li><li>标题用一款有个性的字体（几何无衬线或思源宋体），正文保持系统字体保证加载速度</li><li>中文 web font 按需子集化，只给标题，控制体积</li></ul><h2 id="细节层-锦上添花" tabindex="-1">细节层（锦上添花） <a class="header-anchor" href="#细节层-锦上添花" aria-label="Permalink to &quot;细节层（锦上添花）&quot;">​</a></h2><ul><li><strong>步骤竖向时间线</strong>：数字徽章 + 连接线，替代普通 H3 标题，教程有「流程感」</li><li>feature 卡重排，拉大留白，hover 微交互</li><li>导航栏滚动玻璃态</li><li>章节滚动入场动效（克制，受 prefers-reduced-motion 约束）</li></ul><h2 id="成本与风险" tabindex="-1">成本与风险 <a class="header-anchor" href="#成本与风险" aria-label="Permalink to &quot;成本与风险&quot;">​</a></h2><ul><li>母题曲线、图片外框：纯 CSS，零依赖</li><li>自定义字体：中文 web font 增加加载体积，需按需子集化</li><li>整套铺开需一轮设计 + 逐页验证</li></ul><h2 id="执行建议" tabindex="-1">执行建议 <a class="header-anchor" href="#执行建议" aria-label="Permalink to &quot;执行建议&quot;">​</a></h2><p>不一次性全站开工。先做<strong>首页 + 一个教程页</strong>的完整视觉预览（母题航线 + hero 重做 + 截图外框 + 底色字体），截图确认后再铺到全站。改动范围可控。</p><h2 id="待用户确认的开放项" tabindex="-1">待用户确认的开放项 <a class="header-anchor" href="#待用户确认的开放项" aria-label="Permalink to &quot;待用户确认的开放项&quot;">​</a></h2><ul><li>是否引入自定义字体（体积 vs 质感）</li><li>航线母题的强度（是否觉得多余）</li><li>截图外框对手机截图的处理方式（套设备壳 vs 仅圆角阴影）</li></ul>',23)])])}const b=e(o,[["render",t]]);export{_ as __pageData,b as default};
